            tree[j] += delta
            j += j & -j
    def select(rank):
        pos, accumulated = 0,0
        step = 1 << (u.bit_length()-1)
        while step:
            candidate = pos+step
            if candidate <= u and accumulated+tree[candidate] < rank:
                accumulated += tree[candidate]
                pos = candidate
            step //= 2
